"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, useId, useRef, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { ChevronDownIcon } from "../parts/icons";
import {
  AXIS_TOP,
  type Period,
  PERIOD_NAMES,
  PERIODS,
  readPeriod,
} from "./budget-variance/data";
import { describeRow, RowFigures } from "./budget-variance/row-figures";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

const AXIS = [0, 0.5, 1, AXIS_TOP];

/**
 * Spend against budget for each team on one shared percent axis, with the
 * company total on top. The period switch springs every bar and rolls every
 * amount together. A team opens in place to show its budget lines. Arrow
 * keys, Home and End move between teams.
 */
export function BudgetVariance({ className }: { className?: string }) {
  const titleId = useId();
  const reduceMotion = useReducedMotion();
  const [period, setPeriod] = useState<Period>("month");
  const [open, setOpen] = useState<string | null>("product");
  const [hovered, setHovered] = useState<string | null>(null);
  const [focusId, setFocusId] = useState("product");
  const buttons = useRef(new Map<string, HTMLButtonElement>());
  const { total, teams } = readPeriod(period);

  const onListKeyDown = (event: KeyboardEvent<HTMLUListElement>) => {
    const current = teams.findIndex((team) => team.id === focusId);
    let next: number;
    if (event.key === "ArrowDown")
      next = Math.min(teams.length - 1, current + 1);
    else if (event.key === "ArrowUp") next = Math.max(0, current - 1);
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = teams.length - 1;
    else return;
    event.preventDefault();
    const team = teams[next];
    if (!team) return;
    setFocusId(team.id);
    buttons.current.get(team.id)?.focus();
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Budget against actual
          </h2>
          <p className="text-sm text-muted-foreground">
            Fernhill operating spend, {PERIOD_NAMES[period]}
          </p>
        </div>
        <SegmentedControl
          aria-label="Period"
          options={PERIODS}
          value={period}
          onValueChange={setPeriod}
        />
      </header>

      <div className="flex flex-col gap-4 p-5">
        <div
          aria-hidden="true"
          className="relative mr-10 ml-3 h-4 text-xs text-muted-foreground"
        >
          {AXIS.map((tick) => (
            <span
              key={tick}
              className={cn(
                "left-(--x) absolute",
                tick === 0
                  ? ""
                  : tick === AXIS_TOP
                    ? "-translate-x-full"
                    : "-translate-x-1/2",
              )}
              style={
                // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                { "--x": `${(tick / AXIS_TOP) * 100}%` } as VarStyle
              }
            >
              {Math.round(tick * 100)}%
            </span>
          ))}
        </div>

        <div
          className="rounded-xl border border-border py-3 pr-10 pl-3"
          aria-live="polite"
          aria-atomic="true"
        >
          <RowFigures row={total} fill="bg-foreground" />
          <span className="sr-only">for {PERIOD_NAMES[period]}</span>
        </div>

        <ul
          aria-label="Teams. Use the arrow keys to move between teams."
          onKeyDown={onListKeyDown}
          className="flex flex-col gap-1"
        >
          {teams.map((team) => {
            const expanded = open === team.id;
            const faded = hovered !== null && hovered !== team.id;
            const panelId = `${titleId}-${team.id}`;
            return (
              <li
                key={team.id}
                onPointerEnter={() => setHovered(team.id)}
                onPointerLeave={() => setHovered(null)}
                className="rounded-xl"
              >
                <Button
                  ref={(node) => {
                    if (node) buttons.current.set(team.id, node);
                    else buttons.current.delete(team.id);
                  }}
                  type="button"
                  variant="ghost"
                  tabIndex={team.id === focusId ? 0 : -1}
                  aria-expanded={expanded}
                  aria-controls={panelId}
                  aria-label={`${team.name}, ${describeRow(team)}`}
                  onFocus={() => {
                    setFocusId(team.id);
                    setHovered(team.id);
                  }}
                  onBlur={() => setHovered(null)}
                  onClick={() => setOpen(expanded ? null : team.id)}
                  className="h-auto w-full items-start justify-start text-left whitespace-normal"
                >
                  <span className="flex w-full items-start gap-3 py-1 font-normal">
                    <RowFigures row={team} fill={team.fill} faded={faded} />
                    <ChevronDownIcon
                      aria-hidden="true"
                      className={cn(
                        "mt-0.5 size-4 shrink-0 text-muted-foreground motion-safe:transition-transform",
                        expanded && "rotate-180",
                      )}
                    />
                  </span>
                </Button>
                <AnimatePresence initial={false}>
                  {expanded ? (
                    <motion.ul
                      id={panelId}
                      aria-label={`${team.name} budget lines`}
                      initial={
                        reduceMotion
                          ? { opacity: 0 }
                          : { height: 0, opacity: 0 }
                      }
                      animate={
                        reduceMotion
                          ? { opacity: 1 }
                          : { height: "auto", opacity: 1 }
                      }
                      exit={
                        reduceMotion
                          ? { opacity: 0 }
                          : { height: 0, opacity: 0 }
                      }
                      transition={{
                        duration: 0.25,
                        ease: [0.165, 0.84, 0.44, 1],
                      }}
                      className="overflow-hidden"
                    >
                      {team.lines.map((line) => (
                        <li
                          key={line.id}
                          className="ml-6 border-l border-border py-2 pr-10 pl-4"
                        >
                          <RowFigures
                            row={line}
                            fill={team.fill}
                            faded={faded}
                            small
                          />
                        </li>
                      ))}
                    </motion.ul>
                  ) : null}
                </AnimatePresence>
              </li>
            );
          })}
        </ul>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

