/** One row of figures: what was planned and what was spent in the period. */
export interface BudgetRow {
  id: string;
  name: string;
  budget: number;
  actual: number;
}

/** A team's figures with its colour and its lines. */
export interface TeamRow extends BudgetRow {
  fill: string;
  lines: BudgetRow[];
}

/** Every team's figures for one period, plus the company total. */
export function readPeriod(period: Period) {
  const months = MONTHS[period];
  const teams = TEAMS.map((team): TeamRow => {
    const lines = team.lines.map((line, index) => ({
      id: `${team.id}-${index}`,
      name: line.name,
      budget: line.monthly * months,
      actual: line.monthly * months * line.spent[period],
    }));
    return {
      id: team.id,
      name: team.name,
      fill: team.fill,
      lines,
      budget: lines.reduce((sum, line) => sum + line.budget, 0),
      actual: lines.reduce((sum, line) => sum + line.actual, 0),
    };
  });
  return {
    total: {
      id: "total",
      name: "Total operating spend",
      budget: teams.reduce((sum, team) => sum + team.budget, 0),
      actual: teams.reduce((sum, team) => sum + team.actual, 0),
    },
    teams,
  };
}

const SHORT = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  notation: "compact",
  minimumFractionDigits: 1,
  maximumFractionDigits: 1,
});
const SHORTER = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  notation: "compact",
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

/** A dollar amount in short form with a fixed number of places, such as $34.8K or $1.37M, so its digits can roll. */
export const formatAmount = (value: number) =>
  (Math.abs(value) >= 1_000_000 ? SHORTER : SHORT).format(value);

/** The furthest the shared axis reaches, as a share of budget. Spend past it is clipped at the edge. */
export const AXIS_TOP = 1.25;

import { cn } from "@/lib/utils";

import { RollingText } from "../../parts/rolling-text";
import { BudgetBar } from "./budget-bar";
import { type BudgetRow, formatAmount } from "./data";

/** Props for the figures of one row. */
export interface RowFiguresProps {
  row: BudgetRow;
  fill: string;
  faded?: boolean;
  /** Smaller type and a thinner bar, for a line inside a team. */
  small?: boolean;
}

/** The spoken summary of a row, such as "$1.37M of $1.42M, $48.9K under budget". */
export function describeRow(row: BudgetRow): string {
  const gap = row.actual - row.budget;
  return `${formatAmount(row.actual)} of ${formatAmount(row.budget)}, ${formatAmount(Math.abs(gap))} ${gap > 0 ? "over" : "under"} budget`;
}

/**
 * A row's name, spend of budget, bullet bar and the amount over or under.
 * Every amount rolls to its new value when the period changes.
 */
export function RowFigures({
  row,
  fill,
  faded,
  small = false,
}: RowFiguresProps) {
  const gap = row.actual - row.budget;
  const share = row.budget === 0 ? 0 : (Math.abs(gap) / row.budget) * 100;
  const over = gap > 0;

  return (
    <span className="grid w-full min-w-0 grid-cols-[1fr_auto] items-end gap-x-4 gap-y-2">
      <span className="flex min-w-0 flex-col">
        <span
          className={cn("truncate", small ? "text-sm" : "text-sm font-medium")}
        >
          {row.name}
        </span>
        <span
          aria-hidden="true"
          className="flex gap-1 text-xs text-muted-foreground"
        >
          <RollingText text={formatAmount(row.actual)} /> of{" "}
          <RollingText text={formatAmount(row.budget)} />
        </span>
      </span>
      <span aria-hidden="true" className="flex flex-col items-end">
        <span
          className={cn(
            "text-sm font-medium",
            over ? "text-marketing-orange-ink" : "text-marketing-green-ink",
          )}
        >
          {over ? "+" : "-"}
          <RollingText text={formatAmount(Math.abs(gap))} />
        </span>
        <span className="flex gap-1 text-xs text-muted-foreground">
          <RollingText text={`${share.toFixed(1)}%`} />
          {over ? "over" : "under"}
        </span>
      </span>
      <span className="sr-only">{describeRow(row)}</span>
      <span className="col-span-2">
        <BudgetBar
          budget={row.budget}
          actual={row.actual}
          fill={fill}
          faded={faded}
          thin={small}
        />
      </span>
    </span>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";

import { cn } from "@/lib/utils";

import { AXIS_TOP } from "./data";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for one bullet bar. */
export interface BudgetBarProps {
  budget: number;
  actual: number;
  /** The background class of the spend inside budget, such as `bg-chart-1`. */
  fill: string;
  /** Set on the bars of rows that are not hovered, so the hovered row stands out. */
  faded?: boolean;
  /** A thinner bar for the lines inside a team. */
  thin?: boolean;
}

// Critically damped (damping is 2 * sqrt(stiffness)): every bar lands on its new length together, with no wobble.
const SPRING: Transition = {
  type: "spring",
  stiffness: 210,
  damping: 29,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

const BUDGET_MARK = 100 / AXIS_TOP;

/**
 * Spend against budget on the shared axis. The tick marks the budget; spend
 * inside it takes the team colour, and spend past it is the same bar clipped
 * to the space after the tick, in the warning colour. Decorative: the row says the figures.
 */
export function BudgetBar({
  budget,
  actual,
  fill,
  faded = false,
  thin = false,
}: BudgetBarProps) {
  const reduceMotion = useReducedMotion();
  const transition = reduceMotion ? INSTANT : SPRING;
  const ratio = budget === 0 ? 0 : actual / budget;
  const within = Math.min(ratio, 1) * BUDGET_MARK;
  const over = Math.max(0, Math.min(ratio, AXIS_TOP) - 1) * BUDGET_MARK;

  return (
    <div
      aria-hidden="true"
      className={cn(
        "relative w-full rounded-full bg-muted motion-safe:transition-opacity motion-safe:duration-200",
        thin ? "h-1.5" : "h-2.5",
        faded && "opacity-40",
      )}
    >
      <motion.span
        initial={false}
        animate={{ width: `${within}%` }}
        transition={transition}
        className={cn("absolute inset-y-0 left-0 rounded-full", fill)}
      />
      <motion.span
        initial={false}
        animate={{ width: `${over}%` }}
        transition={transition}
        className="left-(--x) absolute inset-y-0 rounded-r-full bg-marketing-orange-ink"
        style={
          // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
          { "--x": `${BUDGET_MARK}%` } as VarStyle
        }
      />
      <span
        className="left-(--x) absolute -inset-y-1 w-0.5 rounded-full bg-foreground"
        style={
          // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
          { "--x": `${BUDGET_MARK}%` } as VarStyle
        }
      />
    </div>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };
